"""Strip everything but the picture out of a PNG before it is handed over.

Templates generated by ChatGPT carry a `caBX` chunk — a 23 KB C2PA Content
Credentials record saying the image was produced by AI. `cv2.imwrite` does not
copy it, so today's output is already clean; this pass makes that a guarantee
instead of a side effect of the encoder, and cleans files made elsewhere.

It does NOT change what an image-reading bot sees: text baked into the pixels
stays where it is. Marketplace checks that quote on-image text are doing OCR,
not reading metadata.
"""

from __future__ import annotations

import pathlib
import struct

from .errors import UserError

PNG_MAGIC = b"\x89PNG\r\n\x1a\n"

# Kept: the image itself plus the chunks that decide how its colours are shown.
# Dropping sRGB/gAMA/iCCP would silently shift every colour in some viewers,
# which is the one thing a colour-accuracy tool must never do.
KEEP_CHUNKS = frozenset(
    {"IHDR", "PLTE", "IDAT", "IEND", "tRNS", "sRGB", "gAMA", "cHRM", "iCCP", "sBIT"}
)


def _split_chunks(data: bytes) -> list[tuple[str, bytes]]:
    """-> [(type, whole chunk incl. length and CRC)]."""
    chunks: list[tuple[str, bytes]] = []
    offset = 8
    while offset + 8 <= len(data):
        (length,) = struct.unpack(">I", data[offset : offset + 4])
        kind = data[offset + 4 : offset + 8].decode("latin1")
        end = offset + 12 + length
        if end > len(data):
            raise UserError("PNG обірваний — довжина чанка виходить за межі файлу")
        chunks.append((kind, data[offset:end]))
        offset = end
        if kind == "IEND":
            break
    return chunks


def inspect(path) -> list[tuple[str, int]]:
    """-> [(chunk type, payload size)] for everything that is not the picture."""
    path = pathlib.Path(path)
    data = path.read_bytes()
    if not data.startswith(PNG_MAGIC):
        return []
    return [
        (kind, len(raw) - 12)
        for kind, raw in _split_chunks(data)
        if kind not in KEEP_CHUNKS
    ]


def strip_file(path) -> list[str]:
    """Rewrite the PNG without its metadata chunks. -> what was removed.

    The file is left untouched when there is nothing to remove, so a clean batch
    costs one read and no write — and, just as important, keeps the timestamps
    the stamping step may already have set.
    """
    path = pathlib.Path(path)
    try:
        data = path.read_bytes()
    except OSError as exc:
        raise UserError(f"не вдалося прочитати {path.name}: {exc}") from None
    if not data.startswith(PNG_MAGIC):
        return []

    chunks = _split_chunks(data)
    removed = [kind for kind, _ in chunks if kind not in KEEP_CHUNKS]
    if not removed:
        return []

    cleaned = PNG_MAGIC + b"".join(raw for kind, raw in chunks if kind in KEEP_CHUNKS)
    try:
        path.write_bytes(cleaned)
    except OSError as exc:
        raise UserError(f"не вдалося перезаписати {path.name}: {exc}") from None
    return removed


def strip_files(paths) -> list[tuple[pathlib.Path, list[str]]]:
    """Clean each path. -> only the files that actually carried something."""
    touched: list[tuple[pathlib.Path, list[str]]] = []
    for path in paths:
        removed = strip_file(path)
        if removed:
            touched.append((pathlib.Path(path), removed))
    return touched


def collect_pngs(target, recursive: bool = True) -> list[pathlib.Path]:
    """One file, or every PNG under a folder."""
    target = pathlib.Path(target).expanduser()
    if target.is_file():
        return [target]
    if not target.is_dir():
        raise UserError(f"не знайдено: {target}")
    pattern = "**/*.png" if recursive else "*.png"
    return sorted(target.glob(pattern))
